func handleAPIVoicePacks(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	packs, err := ListVoicePacks()
	if err != nil {
		http.Error(w, "Failed to list voice packs: "+err.Error(), http.StatusInternalServerError)
		return
	}
	if packs == nil {
		packs = []string{}
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(packs)
}

type TriggerWarningRequest struct {
	Plate     string `json:"plate"`
	VoicePack string `json:"voice_pack"`
	Immediate bool   `json:"immediate"`
}

func handleAPITriggerVehicleWarning(w http.ResponseWriter, r *http.Request, cfg *Config) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req TriggerWarningRequest
	err := json.NewDecoder(r.Body).Decode(&req)
	if err != nil {
		http.Error(w, "Invalid JSON body: "+err.Error(), http.StatusBadRequest)
		return
	}

	if req.Plate == "" {
		http.Error(w, "Placa é obrigatória", http.StatusBadRequest)
		return
	}
	if req.VoicePack == "" {
		req.VoicePack = "default"
	}

	displayName, err := TriggerVehicleWarning(cfg, req.Plate, req.VoicePack, req.Immediate)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "success",
		"message": fmt.Sprintf("Aviso de placa acionado com sucesso: %s", displayName),
	})
}"

