"// TriggerVehicleWarning compiles the audio and pushes it to the Liquidsoap warnings queue (ducking the background music).
func TriggerVehicleWarning(cfg *Config, plate string, voicePack string, immediate bool) (string, error) {
	outputFile, durationSecs, err := CompileVehicleWarning(cfg, plate, voicePack)
	if err != nil {
		return "", err
	}

	displayName := fmt.Sprintf("Aviso de Placa: %s", NormalizePlate(plate))
	LogLocal("WARNING", "[Warning] Aviso de placa acionado: '%s' (Duração: %ds, Ducking: %v)", displayName, durationSecs, immediate)

	// Call the push_warning endpoint on Liquidsoap (runs on port 7000)
	escapedPath := strings.ReplaceAll(outputFile, `\`, `/`)
