func TriggerVehicleWarning(cfg *Config, plate string, voicePack string, immediate bool) (string, error) {
	outputFile, durationSecs, err := CompileVehicleWarning(cfg, plate, voicePack)
	if err != nil {
		return "", err
	}

	// Construct PlayItem
	displayName := fmt.Sprintf("Aviso de Placa: %s", NormalizePlate(plate))
	item := PlayItem{
		ID:              fmt.Sprintf("warning_%d", time.Now().UnixNano()),
		Type:            "event", // Plays at event volume level
		DisplayName:     displayName,
		FileName:        filepath.Base(outputFile),
		LocalPath:       outputFile,
		DurationSeconds: durationSecs,
		CueIn:           0.0,
		CueOut:          float64(durationSecs),
		Amplify:         1.0,
	}

	// Prepend to front of playQueue (thread-safe)
	schedMutex.Lock()
	playQueue = append([]PlayItem{item}, playQueue...)
	schedMutex.Unlock()

	LogLocal("WARNING", "[Warning] Aviso de placa acionado: '%s' (Duração: %ds, Imediato: %v)", displayName, durationSecs, immediate)

	if immediate {
		// Trigger skip in Liquidsoap
		go func() {
			RegisterIntentionalSkip()
			client := &http.Client{Timeout: 2 * time.Second}
			resp, err := client.Get("http://127.0.0.1:7000/flush_and_skip")
			if err != nil {
				LogLocal("ERROR", "[Warning] Falha ao enviar skip ao Liquidsoap: %v", err)
			} else {
				io.Copy(io.Discard, resp.Body)
				resp.Body.Close()
				LogLocal("INFO", "[Warning] Skip enviado com sucesso ao Liquidsoap")
			}
		}()
	}

	return displayName, nil
}"

