	dirs, err := os.ReadDir(chimesDir)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, d := range dirs {
		if !d.IsDir() {
			name := d.Name()
			ext := strings.ToLower(filepath.Ext(name))
			if ext == ".mp3" || ext == ".wav" {
				files = append(files, name)
			}
		}
	}
	return files, nil
}

