"        async function loadVoicePacks() {
            try {
                const res = await fetch('/api/voice-packs');
                if (!res.ok) throw new Error(await res.text());
                const packs = await res.json();
                const select = document.getElementById('warning-voice-select');
                select.innerHTML = '';
                if (packs.length === 0) {
                    select.innerHTML = '<option value="">Nenhum pacote encontrado (crie uma pasta em voice_packs/)</option>';
                    return;
                }
                packs.forEach(p => {
                    const opt = document.createElement('option');
                    opt.value = p;
                    opt.textContent = p;
                    select.appendChild(opt);
                });
            } catch (err) {
                console.error("Failed to load voice packs:", err);
            }
        }

        async function loadChimes() {
            try {
                const res = await fetch('/api/chimes');
                if (!res.ok) throw new Error("API error");
                const files = await res.json();

                const select = document.getElementById('warning-chime-select');
                if (!select) return;
                select.innerHTML = '';

                // Ordenar para colocar 'default.mp3' e 'default.wav' no topo
                files.sort((a, b) => {
                    const isDefA = a.toLowerCase().startsWith('default.');
                    const isDefB = b.toLowerCase().startsWith('default.');
                    if (isDefA && !isDefB) return -1;
                    if (!isDefA && isDefB) return 1;
                    return a.localeCompare(b);
                });

