"package main

import (
	"context"
	"encoding/json"
	"fmt"
	"os"

	"github.com/jackc/pgx/v5"
)

func main() {
	databaseURL := "postgres://neoroute:@@Mo1isc00@@@192.168.15.250:5432/imc_server?sslmode=disable"
	ctx := context.Background()

	conn, err := pgx.Connect(ctx, databaseURL)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Unable to connect to database: %v\n", err)
		os.Exit(1)
	}
	defer conn.Close(ctx)

	rows, err := conn.Query(ctx, "SELECT custom_styles_json::text FROM basic_schedules")
	if err != nil {
		fmt.Printf("Error querying basic_schedules: %v\n", err)
		return
	}
	defer rows.Close()

	distinctNames := make(map[string]bool)
	for rows.Next() {
		var customStyles *string
		if errScan := rows.Scan(&customStyles); errScan == nil && customStyles != nil && *customStyles != "" {
			var stylesMap map[string][]string
			if err := json.Unmarshal([]byte(*customStyles), &stylesMap); err == nil {
				for _, names := range stylesMap {
					for _, name := range names {
						distinctNames[name] = true
					}
				}
			}
		}
	}

	fmt.Println("Distinct style names found in basic_schedules JSON:")
	for name := range distinctNames {
		fmt.Printf("  - %s\n", name)
	}
}
"

"package main

import (
	"context"
	"fmt"
	"os"

	"github.com/jackc/pgx/v5"
)

func main() {
	databaseURL := "postgres://neoroute:@@Mo1isc00@@@192.168.15.250:5432/imc_server?sslmode=disable"
	ctx := context.Background()

	conn, err := pgx.Connect(ctx, databaseURL)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Unable to connect to database: %v\n", err)
		os.Exit(1)
	}
	defer conn.Close(ctx)

	// List of renames to perform
	renames := []struct {
		from string
		to   string
	}{
		{"Z- (TESTE) Agradaveis POP Rock", "0 - (TESTE) Agradaveis POP Rock"},
		{"Z - (TESTE) Anos 70", "0 - (TESTE) Anos 70"},
		{"Z - (TESTE) Anos 80", "0 - (TESTE) Anos 80"},
		{"Z - (TESTE) Anos 90", "0 - (TESTE) Anos 90"},
		{"Z- (TESTE) Dance Antigas", "0 - (TESTE) Dance Antigas"},
		{"Z - (TESTE) EURODANCE ANOS 80", "0 - (TESTE) EURODANCE ANOS 80"},
		{"Z - (TESTE) LOVE METAL", "0 - (TESTE) LOVE METAL"},
		{"Z - (TESTE) Remixes 2025", "0 - (TESTE) Remixes 2025"},
		{"Z - (TESTE) TEMAS COMERCIAIS HOLLYWOOD", "0 - (TESTE) TEMAS COMERCIAIS HOLLYWOOD"},
	}

	fmt.Println("Starting database fix for style names...")
	for _, r := range renames {
		tag, err := conn.Exec(ctx, "UPDATE music_styles SET name = $1 WHERE name = $2", r.to, r.from)
		if err != nil {
			fmt.Printf("Error renaming %s -> %s: %v\n", r.from, r.to, err)
		} else {
			fmt.Printf("Renamed %s -> %s (Rows affected: %d)\n", r.from, r.to, tag.RowsAffected())
		}
	}
	fmt.Println("Done!")
}
"

